const triggerData = $('Execute Trigger').first().json;
const tasks = $input.all();

if (!tasks || tasks.length === 0) {
  return [{ json: { error: true, output: 'No tasks found in your list.' } }];
}

// Find best matching task by title (case-insensitive partial match)
const searchQuery = (triggerData.search_query || '').toLowerCase();
const match = tasks.find(t => 
  t.json.title?.toLowerCase().includes(searchQuery)
);

if (!match) {
  return [{ json: { error: true, output: `No task found matching "${triggerData.search_query}". Check the task name and try again.` } }];
}

const updates = {};
if (triggerData.new_title) updates.title = triggerData.new_title;
if (triggerData.new_due_date) updates.due = triggerData.new_due_date;
if (triggerData.new_notes !== undefined) updates.notes = triggerData.new_notes;
if (triggerData.mark_complete === true || triggerData.mark_complete === 'true') {
  updates.status = 'completed';
  updates.completed = new Date().toISOString();
}

return [{ json: { taskId: match.json.id, updates, originalTitle: match.json.title } }];

const task = $input.first().json;
const triggerData = $('Execute Trigger').first().json;
let msg = '';
if (triggerData.mark_complete === true || triggerData.mark_complete === 'true') {
  msg = `Task "${task.title}" marked as complete. Nice work!`;
} else {
  msg = `Task "${task.title}" updated successfully.`;
  if (task.due) {
    const due = new Date(task.due).toLocaleDateString('en-IN', {
      weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata'
    });
    msg += ` Due ${due}.`;
  }
}
return [{ json: { output: msg } }];
